using System;

namespace SftpSync.UI
{
    public static class Program
    {
        [STAThread] // Obligatoire pour que Windows autorise l'interface graphique (WPF)
        public static void Main()
        {
            // On crée le moteur d'application WPF
            var app = new System.Windows.Application();
            
            // On instancie notre fenêtre principale codée en C#
            var mainWindow = new MainWindow();
            
            // On demande à Windows d'afficher la fenêtre et de lancer l'application
            app.Run(mainWindow);
        }
    }
}
